from __future__ import annotations

from collections import Counter, defaultdict
import math
from pathlib import Path
import statistics

from .io import read_jsonl, write_json, write_jsonl
from .scoring import normalize_answer


LENS_MODES = ("lens_compact", "lens_balanced", "lens_detailed")


def _mean(values: list[float]) -> float | None:
    return statistics.fmean(values) if values else None


def _median(values: list[float]) -> float | None:
    return statistics.median(values) if values else None


def _p95(values: list[float]) -> float | None:
    if not values:
        return None
    ordered = sorted(values)
    index = (len(ordered) - 1) * 0.95
    lower = math.floor(index)
    upper = math.ceil(index)
    if lower == upper:
        return ordered[lower]
    return ordered[lower] + (ordered[upper] - ordered[lower]) * (index - lower)


def _metric(rows: list[dict]) -> dict:
    successful = [row for row in rows if row["status"] == "ok"]
    correct = sum(row["correct"] is True for row in successful)
    return {
        "requested": len(rows),
        "successful": len(successful),
        "failed": len(rows) - len(successful),
        "correct": correct,
        "accuracy": correct / len(successful) if successful else None,
    }


def _group(rows: list[dict], keys: tuple[str, ...]) -> list[dict]:
    groups = defaultdict(list)
    for row in rows:
        groups[tuple(row[key] for key in keys)].append(row)
    return [
        {**dict(zip(keys, values)), **_metric(members)}
        for values, members in sorted(groups.items())
    ]


def _paired(rows: list[dict]) -> list[dict]:
    by_key = {(row["question_id"], row["mode"]): row for row in rows}
    output = []
    for mode in LENS_MODES:
        counts = Counter()
        for question_id in sorted({row["question_id"] for row in rows}):
            question_only = by_key.get((question_id, "question_only"))
            lens = by_key.get((question_id, mode))
            if question_only is None or lens is None:
                continue
            if question_only["status"] != "ok" or lens["status"] != "ok":
                counts["excluded_failure"] += 1
                continue
            q_correct = bool(question_only["correct"])
            lens_correct = bool(lens["correct"])
            counts[
                f"question_only_{'correct' if q_correct else 'wrong'}_lens_"
                f"{'correct' if lens_correct else 'wrong'}"
            ] += 1
        output.append(
            {
                "lens_mode": mode,
                "paired_successful": sum(counts.values()) - counts["excluded_failure"],
                "question_only_wrong_lens_correct": counts[
                    "question_only_wrong_lens_correct"
                ],
                "question_only_correct_lens_correct": counts[
                    "question_only_correct_lens_correct"
                ],
                "question_only_correct_lens_wrong": counts[
                    "question_only_correct_lens_wrong"
                ],
                "question_only_wrong_lens_wrong": counts["question_only_wrong_lens_wrong"],
                "excluded_failure": counts["excluded_failure"],
            }
        )
    return output


def _performance(rows: list[dict]) -> list[dict]:
    groups = defaultdict(list)
    for row in rows:
        groups[row["mode"]].append(row)
    output = []
    for mode, members in sorted(groups.items()):
        latency = [float(row["latency_ms"]) for row in members if row["status"] == "ok"]
        ttft = [
            float(row["time_to_first_token_ms"])
            for row in members
            if row["status"] == "ok" and row["time_to_first_token_ms"] is not None
        ]
        speed = [
            float(row["tokens_per_second"])
            for row in members
            if row["status"] == "ok" and row["tokens_per_second"] is not None
        ]
        prompt_tokens = [
            int(row.get("usage", {}).get("prompt_tokens", 0)) for row in members
        ]
        output_tokens = [
            int(row.get("usage", {}).get("completion_tokens", 0)) for row in members
        ]
        total_tokens = [int(row.get("usage", {}).get("total_tokens", 0)) for row in members]
        output.append(
            {
                "mode": mode,
                "requests": len(members),
                "latency_ms": {
                    "mean": _mean(latency),
                    "median": _median(latency),
                    "p95": _p95(latency),
                },
                "time_to_first_token_ms": {
                    "measured": len(ttft),
                    "mean": _mean(ttft),
                    "median": _median(ttft),
                    "p95": _p95(ttft),
                },
                "tokens_per_second": {
                    "measured": len(speed),
                    "mean": _mean(speed),
                    "median": _median(speed),
                    "p95": _p95(speed),
                },
                "tokens": {
                    "prompt_total": sum(prompt_tokens),
                    "prompt_mean": _mean(prompt_tokens),
                    "output_total": sum(output_tokens),
                    "output_mean": _mean(output_tokens),
                    "total": sum(total_tokens),
                    "total_mean": _mean(total_tokens),
                },
            }
        )
    return output


def _cold_warm(rows: list[dict]) -> dict:
    successful = sorted(
        (row for row in rows if row["status"] == "ok"),
        key=lambda row: row["timestamp_utc"],
    )
    if not successful:
        return {"cold_first_request": None, "warm_requests": None}
    cold = successful[0]
    warm_latency = [float(row["latency_ms"]) for row in successful[1:]]
    return {
        "cold_first_request": {
            "question_id": cold["question_id"],
            "mode": cold["mode"],
            "latency_ms": cold["latency_ms"],
            "time_to_first_token_ms": cold["time_to_first_token_ms"],
            "tokens_per_second": cold["tokens_per_second"],
        },
        "warm_requests": {
            "count": len(warm_latency),
            "latency_ms_mean": _mean(warm_latency),
            "latency_ms_median": _median(warm_latency),
            "latency_ms_p95": _p95(warm_latency),
        },
    }


def _repeatability(primary: list[dict], repeats: list[dict]) -> dict:
    repeat_image_ids = {row["image_id"] for row in repeats}
    baseline = [row for row in primary if row["image_id"] in repeat_image_ids]
    groups = defaultdict(list)
    for row in baseline + repeats:
        groups[(row["question_id"], row["mode"])].append(row)
    by_mode = defaultdict(list)
    excluded = 0
    for (_, mode), members in groups.items():
        members.sort(key=lambda row: row["repeat_index"])
        if len(members) != 3 or any(row["status"] != "ok" for row in members):
            excluded += 1
            continue
        answers = [row["normalized_answer"] for row in members]
        by_mode[mode].append(len(set(answers)) == 1)
    details = [
        {
            "mode": mode,
            "groups": len(values),
            "exact_stable_groups": sum(values),
            "exact_stability_rate": sum(values) / len(values) if values else None,
        }
        for mode, values in sorted(by_mode.items())
    ]
    return {
        "status": "complete" if len(repeats) == 416 and len(baseline) == 208 else "incomplete",
        "definition": "all three normalized answers are identical",
        "primary_baseline_requests": len(baseline),
        "repeat_requests": len(repeats),
        "expected_repeat_requests": 416,
        "measured_groups": sum(len(values) for values in by_mode.values()),
        "excluded_groups": excluded,
        "by_mode": details,
    }


def _failure_candidates(rows: list[dict]) -> list[dict]:
    candidates = []
    for row in rows:
        if row["mode"] not in LENS_MODES or row["correct"] is True:
            continue
        if row["status"] != "ok":
            hint = "E_RUNTIME_FAILURE"
        else:
            evidence = normalize_answer(row["lens_text"] or "", row["category"])
            accepted = [
                normalize_answer(answer, row["category"]) for answer in row["accepted_answers"]
            ]
            hint = (
                "C_ANSWER_STRING_PRESENT"
                if any(answer and answer in evidence for answer in accepted)
                else "A_OR_B_OR_D_REQUIRES_SEMANTIC_REVIEW"
            )
        candidates.append(
            {
                "image_id": row["image_id"],
                "question_id": row["question_id"],
                "category": row["category"],
                "mode": row["mode"],
                "question": row["question"],
                "ground_truth": row["ground_truth"],
                "lens_text": row["lens_text"],
                "raw_model_answer": row["raw_model_answer"],
                "automated_review_hint": hint,
            }
        )
    return candidates


def analyze(phase4_root: Path, artifact_root: Path) -> dict:
    rows = read_jsonl(artifact_root / "raw-model-responses.jsonl")
    repeats = read_jsonl(artifact_root / "repeatability-results.jsonl")
    descriptions = read_jsonl(phase4_root / "lens-descriptions.jsonl")
    overall_rows = _group(rows, ("mode",))
    question_only = next(
        (row["accuracy"] for row in overall_rows if row["mode"] == "question_only"), None
    )
    overall = {
        "benchmark_version": "KL-P4-TEXT-ONLY-1",
        "model_id": rows[0]["model_id"] if rows else None,
        "requests": len(rows),
        "images": len({row["image_id"] for row in rows}),
        "questions": len({row["question_id"] for row in rows}),
        "source_image_supplied": any(row["source_image_supplied"] for row in rows),
        "results": [
            {
                **row,
                "vision_transfer_uplift_percentage_points": (
                    (row["accuracy"] - question_only) * 100
                    if row["mode"] in LENS_MODES
                    and row["accuracy"] is not None
                    and question_only is not None
                    else None
                ),
            }
            for row in overall_rows
        ],
    }
    category = {"results": _group(rows, ("mode", "category"))}
    paired = _paired(rows)
    performance = {
        "by_mode": _performance(rows),
        "cold_vs_warm": _cold_warm(rows),
    }
    repeatability = _repeatability(rows, repeats)
    token_means = {
        detail: _mean([item["token_counts"][detail] for item in descriptions])
        for detail in ("compact", "balanced", "detailed")
    }
    token_quality = [
        {
            "mode": row["mode"],
            "mean_qwen3_4b_description_tokens": token_means[row["mode"].removeprefix("lens_")],
            "accuracy": row["accuracy"],
            "vision_transfer_uplift_percentage_points": (
                (row["accuracy"] - question_only) * 100
                if row["accuracy"] is not None and question_only is not None
                else None
            ),
        }
        for row in overall_rows
        if row["mode"] in LENS_MODES
    ]
    failures = _failure_candidates(rows)
    hint_counts = Counter(row["automated_review_hint"] for row in failures)
    write_json(artifact_root / "overall-results.json", overall)
    write_json(artifact_root / "category-results.json", category)
    write_json(artifact_root / "paired-results.json", paired)
    write_json(artifact_root / "performance-summary.json", performance)
    write_json(artifact_root / "repeatability-summary.json", repeatability)
    write_json(artifact_root / "token-quality-tradeoff.json", token_quality)
    write_jsonl(artifact_root / "failure-candidates.jsonl", failures)
    write_json(
        artifact_root / "failure-candidates-summary.json",
        {
            "rows": len(failures),
            "automated_hint_counts": dict(hint_counts),
            "limitation": (
                "These are sampling hints only. A/B/C/D labels require manual semantic "
                "adjudication and are not inferred from string matching."
            ),
        },
    )
    return overall
